const sample = {
  "demo": true,
  "firstName": "Nora",
  "lastName": "Rahman",
  "email": "nora@brightline.example",
  "company": "Brightline Studio",
  "title": "Head of Operations",
  "employees": 42,
  "budget": 8000,
  "source": "demo",
  "utmSource": "linkedin",
  "utmMedium": "cpc",
  "utmCampaign": "ops-audit-q1",
  "value": 8000,
  "priorSource": "newsletter"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const touch = String(item.utmSource || item.source || 'direct');
const medium = String(item.utmMedium || 'unknown');
const campaign = String(item.utmCampaign || '(none)');
const value = Number(item.value || item.budget || 0);
let weight = 1;
if (medium === 'cpc') weight = 1.2;
if (medium === 'email') weight = 0.8;
if (touch === 'direct' && item.priorSource) weight = 0.5;
const credited = Math.round(value * weight);
const record = {
  email: item.email || '',
  company: item.company || '',
  touch, medium, campaign, value, weight, credited,
  model: 'last-touch',
};
return {
  summary: record.model + ' credits ' + credited + ' to ' + campaign + ' (' + touch + '/' + medium + ').',
  route: medium === 'cpc' ? 'paid' : 'organic',
  record,
  slackText: campaign + ' credited ' + credited + ' via ' + touch,
  actions: [{ app: 'CRM', operation: 'stamp attribution', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'utm-attribution-stitcher',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
